query Transactions($query: SqlQuery, $limit: Int) {
    transactions(query: $query, limit: $limit) {
      items {
        transaction_id
        merchant_uid
        gross_amount
        net_amount
        currency
        status
        transaction_date
        settlement_batch
        transaction_type
        fee_mode
      }
      total_row_count
    }
  }

query TransactionsByCardAndPayor($query: SqlQuery, $paymentMethodQuery: [QueryPair], $payorQuery: [QueryPair]) {
  transactions(query: $query, limit: 10) {
    items {
      transaction_id
      payment_method(query_list: $paymentMethodQuery) {
        last_four
        payor(query_list: $payorQuery) {
          email
        }
      }
    }
    total_row_count
  }
}

