mutation CreateTransaction(
  $merchant_uid: String!
  $amount: Int!
) {
  createTransaction(
    merchant_uid: $merchant_uid
    amount: $amount
  ) {
    transaction_id
    merchant_uid
    gross_amount
    net_amount
    currency
    status
    fee_mode
    fees
    transaction_type
    transaction_date
  }
}

